/* DRIGHT2 KYC/document security + professional documents + explainable eligibility. */
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('professional-docs','professional-docs',false,20971520,ARRAY['application/pdf','image/jpeg','image/png','image/webp']::text[]) ON CONFLICT(id) DO UPDATE SET public=false,file_size_limit=EXCLUDED.file_size_limit,allowed_mime_types=EXCLUDED.allowed_mime_types;

CREATE TABLE IF NOT EXISTS public.professional_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,profile_type text,document_type text NOT NULL CHECK(document_type IN('cv','resume','certificate','qualification','portfolio','business_registration','professional_license','media_kit','other')),title text,storage_bucket text NOT NULL DEFAULT 'professional-docs',storage_path text NOT NULL,original_file_name text,mime_type text,size_bytes bigint,version integer NOT NULL DEFAULT 1 CHECK(version>0),replaces_document_id uuid REFERENCES public.professional_documents(id),status text NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','under_review','verified','rejected','needs_resubmission','expired')),user_visible_reason text,reviewer_id uuid REFERENCES public.users(id),reviewed_at timestamptz,expires_at timestamptz,is_deleted boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT professional_storage_bucket CHECK(storage_bucket='professional-docs'));
CREATE INDEX IF NOT EXISTS idx_professional_documents_user ON public.professional_documents(user_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_professional_documents_status ON public.professional_documents(status,created_at DESC); ALTER TABLE public.professional_documents ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.professional_document_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES public.professional_documents(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,reviewer_id uuid NOT NULL REFERENCES public.users(id),previous_status text,decision text NOT NULL,new_status text NOT NULL,user_visible_reason text,internal_note text,checklist jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_professional_document_reviews_doc ON public.professional_document_reviews(document_id,created_at DESC); ALTER TABLE public.professional_document_reviews ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS professional_documents_own_read ON public.professional_documents; CREATE POLICY professional_documents_own_read ON public.professional_documents FOR SELECT TO authenticated USING(user_id=auth.uid() AND is_deleted=false);
DROP POLICY IF EXISTS professional_documents_admin_read ON public.professional_documents; CREATE POLICY professional_documents_admin_read ON public.professional_documents FOR SELECT TO authenticated USING(public.has_dright_permission('professional_documents','view'));
DROP POLICY IF EXISTS professional_documents_own_insert ON public.professional_documents; CREATE POLICY professional_documents_own_insert ON public.professional_documents FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND storage_bucket='professional-docs' AND status='submitted' AND reviewer_id IS NULL AND reviewed_at IS NULL);
DROP POLICY IF EXISTS professional_documents_admin_update ON public.professional_documents; CREATE POLICY professional_documents_admin_update ON public.professional_documents FOR UPDATE TO authenticated USING(public.has_dright_permission('professional_documents','review')) WITH CHECK(public.has_dright_permission('professional_documents','review'));
DROP POLICY IF EXISTS professional_document_reviews_admin_read ON public.professional_document_reviews; CREATE POLICY professional_document_reviews_admin_read ON public.professional_document_reviews FOR SELECT TO authenticated USING(public.has_dright_permission('professional_documents','view'));
DROP POLICY IF EXISTS professional_document_reviews_own_read ON public.professional_document_reviews; CREATE POLICY professional_document_reviews_own_read ON public.professional_document_reviews FOR SELECT TO authenticated USING(user_id=auth.uid());
DROP POLICY IF EXISTS users_upload_own_professional_docs ON storage.objects; CREATE POLICY users_upload_own_professional_docs ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='professional-docs' AND owner=auth.uid() AND (storage.foldername(name))[1]=auth.uid()::text);
DROP POLICY IF EXISTS users_read_own_professional_docs ON storage.objects; CREATE POLICY users_read_own_professional_docs ON storage.objects FOR SELECT TO authenticated USING(bucket_id='professional-docs' AND owner=auth.uid() AND (storage.foldername(name))[1]=auth.uid()::text);
DROP POLICY IF EXISTS reviewers_read_professional_docs ON storage.objects; CREATE POLICY reviewers_read_professional_docs ON storage.objects FOR SELECT TO authenticated USING(bucket_id='professional-docs' AND public.has_dright_permission('professional_documents','view'));

