DROP POLICY IF EXISTS update_own_kyc_profile ON public.kyc_profiles; DROP POLICY IF EXISTS admin_read_all_kyc_profiles ON public.kyc_profiles; DROP POLICY IF EXISTS admin_update_all_kyc_profiles ON public.kyc_profiles; DROP POLICY IF EXISTS insert_own_kyc_profile ON public.kyc_profiles; DROP POLICY IF EXISTS select_own_kyc_profile ON public.kyc_profiles; CREATE POLICY kyc_profiles_own_read ON public.kyc_profiles FOR SELECT TO authenticated USING(user_id=auth.uid() AND is_deleted=false); CREATE POLICY kyc_profiles_admin_read ON public.kyc_profiles FOR SELECT TO authenticated USING(public.has_dright_permission('kyc','view')); CREATE POLICY kyc_profiles_own_insert ON public.kyc_profiles FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status IN('not_started','pending_submission') AND reviewer_id IS NULL AND last_reviewed_at IS NULL); CREATE POLICY kyc_profiles_admin_update ON public.kyc_profiles FOR UPDATE TO authenticated USING(public.has_dright_permission('kyc','review')) WITH CHECK(public.has_dright_permission('kyc','review'));
